import{_ as d,a0 as m,w as l,s as u,I as p,x as e,ao as r,a1 as a,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"LFCS 系列第九講: 使用 Yum、RPM、Apt、Dpkg、Aptitude 進行 Linux 軟件包管理 | LCTT x X-CMD","titleTemplate":false,"description":"LFCS 系列第九講: 使用 Yum、RPM、Apt、Dpkg、Aptitude 進行 Linux 軟件包管理 | LCTT (LFCS) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"LFCS 系列第九講: 使用 Yum、RPM、Apt、Dpkg、Aptitude 進行 Linux 軟件包管理 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"LFCS 系列第九講: 使用 Yum、RPM、Apt、Dpkg、Aptitude 進行 Linux 軟件包管理 | LCTT (LFCS) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"LFCS/Part 9 - LFCS--Linux Package Management with Yum RPM Apt Dpkg Aptitude and Zypper","title":"LFCS 系列第九講: 使用 Yum、RPM、Apt、Dpkg、Aptitude 進行 Linux 軟件包管理","tag":"LFCS","desc":""},"relativePath":"LFCS/Part 9 - LFCS--Linux Package Management with Yum RPM Apt Dpkg Aptitude and Zypper.md","filePath":"[post].md"}'),o={name:"LFCS/Part 9 - LFCS--Linux Package Management with Yum RPM Apt Dpkg Aptitude and Zypper.md"};function s(g,t,k,w,f,S){const n=m("Link");return l(),u("div",null,[t[24]||(t[24]=p("h1",{id:"lfcs-系列第九講-使用-yum、rpm、apt、dpkg、aptitude-進行-linux-軟件包管理",tabindex:"-1"},[e("LFCS 系列第九講: 使用 Yum、RPM、Apt、Dpkg、Aptitude 進行 Linux 軟件包管理 "),p("a",{class:"header-anchor",href:"#lfcs-系列第九講-使用-yum、rpm、apt、dpkg、aptitude-進行-linux-軟件包管理","aria-label":"Permalink to “LFCS 系列第九講: 使用 Yum、RPM、Apt、Dpkg、Aptitude 進行 Linux 軟件包管理”"},"​")],-1)),t[25]||(t[25]=p("p",null,"去年八月, Linux基金會宣佈了一個全新的LFCS（Linux Foundation Certified Sysadmin，Linux基金會認證系統管理員）認證計劃，這對廣大系統管理員來説是一個很好的機會，管理員們可以通過認證考試來表明自己可以成功支持Linux系統的整體運營。 一個Linux基金會認證的系統管理員能有足夠的專業知識來確保系統高效運行，提供第一手的故障診斷和監視，並且在需要的情況下將問題提交給工程師支持團隊。",-1)),t[26]||(t[26]=p("p",null,[p("img",{src:"http://www.tecmint.com/wp-content/uploads/2014/11/lfcs-Part-9.png",alt:"Linux Package Management"})],-1)),t[27]||(t[27]=p("p",null,[p("em",null,"Linux基金會認證系統管理員 – 第九講")],-1)),t[28]||(t[28]=p("p",null,"請觀看下面關於Linux基金會認證計劃的演示。",-1)),t[29]||(t[29]=p("p",null,"注：youtube 視頻",-1)),t[30]||(t[30]=p("iframe",{width:"720",height:"405",frameborder:"0",allowfullscreen:"allowfullscreen",src:"http://www.youtube.com/embed/Y29qZ71Kicg"},null,-1)),t[31]||(t[31]=r('<p>本文是本系列教程中的第九講，今天在這篇文章中我們會引導你學習Linux軟件包管理，這也是LFCS認證考試所需要的。</p><h3 id="軟件包管理" tabindex="-1">軟件包管理 <a class="header-anchor" href="#軟件包管理" aria-label="Permalink to “軟件包管理”">​</a></h3><p>簡單的説，軟件包管理是系統中安裝和維護軟件的一種方法，這裏説的維護包含更新和卸載。</p><p>在Linux早期，程序只以源代碼的方式發行，還帶有所需的用户使用手冊和必備的配置文件，甚至更多。現如今，大多數發行商一般使用預裝程序或者被稱為軟件包的程序集合。用户可以使用這些預裝程序或者軟件包安裝到該發行版中。然而，Linux最偉大的一點是我們仍然能夠獲得程序的源代碼用來學習、改進和編譯。</p><p>####軟件包管理系統是如何工作的####</p><p>如果某一個軟件包需要一定的資源，如共享庫，或者需要另一個軟件包，這就稱之為依賴性。所有現在的包管理系統提供了一些解決依賴性的方法，以確保當安裝一個軟件包時，相關的依賴包也安裝好了。</p><p>####打包系統####</p><p>幾乎所有安裝在現代Linux系統上的軟件都會能互聯網上找到。它要麼由發行商通過中央倉庫（中央倉庫能包含幾千個軟件包，每個軟件包都已經為發行版構建、測試並且維護好了）提供，要麼能夠直接得到可以下載和手動安裝的源代碼。</p><p>由於不同的發行版使用不同的打包系統（Debian的*.deb文件/CentOS的*.rpm文件/openSUSE的專門為openSUSE構建的*.rpm文件），因此為一個發行版開發的軟件包會與其他發行版不兼容。然而，大多數發行版都屬於LFCS認證所涉及的三個發行版家族之一。</p><p>####高級和低級打包工具####</p><p>為了有效地進行軟件包管理的任務，你需要知道，有兩種類型的實用工具：低級工具（能在後端實際安裝、升級、卸載軟件包文件），以及高級工具（負責確保能很好的執行依賴性解決和元數據檢索的任務——元數據也稱為數據的數據）。</p><div class="table-wrap"><table><thead><tr><th>發行版</th><th>低級工具</th><th>高級工具</th></tr></thead><tbody><tr><td>Debian版及其衍生版</td><td>dpkg</td><td>apt-get / aptitude</td></tr><tr><td>CentOS版</td><td>rpm</td><td>yum</td></tr><tr><td>openSUSE版</td><td>rpm</td><td>zypper</td></tr></tbody></table></div><p>讓我們來看下低級工具和高級工具的描述。</p><p>dpkg的是基於Debian的系統的一個低級包管理器。它可以安裝，刪除，提供有關資料，以及建立*.deb包，但它不能自動下載並安裝它們相應的依賴包。</p>',14)),p("ul",null,[p("li",null,[t[1]||(t[1]=e("閲讀更多： ",-1)),a(n,{href:"http://www.tecmint.com/dpkg-command-examples/"},{default:i(()=>[...t[0]||(t[0]=[e("15個dpkg命令實例",-1)])]),_:1})])]),t[32]||(t[32]=p("p",null,"apt-get是Debian及其衍生版的高級包管理器，並提供命令列方式來從多個來源檢索和安裝軟件包，其中包括解決依賴性。和dpkg不同的是，apt-get不是直接基於.deb文件工作，而是基於軟件包的正確名稱。",-1)),p("ul",null,[p("li",null,[t[3]||(t[3]=e("閲讀更多： ",-1)),a(n,{href:"http://www.tecmint.com/useful-basic-commands-of-apt-get-and-apt-cache-for-package-management/"},{default:i(()=>[...t[2]||(t[2]=[e("25個apt-get命令實力",-1)])]),_:1})])]),t[33]||(t[33]=p("p",null,"Aptitude是基於Debian的系統的另一個高級包管理器，它可用於快速簡便的執行管理任務（安裝，升級和刪除軟件包，還可以自動處理解決依賴性）。它在atp-get的基礎上提供了更多功能，例如提供對軟件包的幾個版本的訪問。",-1)),t[34]||(t[34]=p("p",null,"rpm是Linux標準基礎（LSB）兼容發行版所使用的一種軟件包管理器，用來對軟件包進行低級處理。就像dpkg一樣，rpm可以查詢、安裝、檢驗、升級和卸載軟件包，它多數用於基於Fedora的系統，比如RHEL和CentOS。",-1)),p("ul",null,[p("li",null,[t[5]||(t[5]=e("閲讀更多： ",-1)),a(n,{href:"http://www.tecmint.com/20-practical-examples-of-rpm-commands-in-linux/"},{default:i(()=>[...t[4]||(t[4]=[e("20個rpm命令實例",-1)])]),_:1})])]),t[35]||(t[35]=p("p",null,"相對於基於RPM的系統，yum增加了系統自動更新的功能和帶依賴性管理的軟件包管理功能。作為一個高級工具，和apt-get或者aptitude相似，yum需要配合倉庫工作。",-1)),p("ul",null,[p("li",null,[t[7]||(t[7]=e("閲讀更多： ",-1)),a(n,{href:"http://www.tecmint.com/20-linux-yum-yellowdog-updater-modified-commands-for-package-mangement/"},{default:i(()=>[...t[6]||(t[6]=[e("20個yum命令實例",-1)])]),_:1})])]),t[36]||(t[36]=r(`<h3 id="低級工具的常見用法" tabindex="-1">低級工具的常見用法 <a class="header-anchor" href="#低級工具的常見用法" aria-label="Permalink to “低級工具的常見用法”">​</a></h3><p>使用低級工具處理最常見的任務如下。</p><p>####1. 從已編譯（<em>.deb或</em>.rpm）的文件安裝一個軟件包####</p><p>這種安裝方法的缺點是沒有提供解決依賴性的方案。當你在發行版本庫中無法獲得某個軟件包並且又不能通過高級工具下載安裝時，你很可能會從一個已編譯文件安裝該軟件包。因為低級工具不會解決依賴性問題，所以當安裝一個沒有解決依賴性的軟件包時會出現出錯並且退出。</p><pre><code># dpkg -i file.deb 		[Debian版和衍生版]
# rpm -i file.rpm 		[CentOS版 / openSUSE版]
</code></pre><p><strong>注意</strong>：不要試圖在CentOS中安裝一個為openSUSE構建的.rpm文件，反之亦然！</p><p>####2. 從已編譯文件中更新一個軟件包####</p><p>同樣，當某個安裝的軟件包不在中央倉庫中時，你只能手動升級該軟件包。</p><pre><code># dpkg -i file.deb 		[Debian版和衍生版]
# rpm -U file.rpm 		[CentOS版 / openSUSE版]
</code></pre><p>####3. 列舉安裝的軟件包####</p><p>當你第一次接觸一個已經在工作中的系統時，很可能你會想知道安裝了哪些軟件包。</p><pre><code># dpkg -l 		[Debian版和衍生版]
# rpm -qa 		[CentOS版 / openSUSE版]
</code></pre>`,12)),p("p",null,[t[9]||(t[9]=e("如果你想知道一個特定的軟件包安裝在哪兒，你可以使用管道命令從以上命令的輸出中去搜索，這在這個系列的",-1)),a(n,{href:"https://linux.cn/article-7161-1.html"},{default:i(()=>[...t[8]||(t[8]=[e("第一講 操作Linux文件",-1)])]),_:1}),t[10]||(t[10]=e(" 中有介紹。例如我們需要驗證mysql-common這個軟件包是否安裝在Ubuntu系統中：",-1))]),t[37]||(t[37]=r(`<pre><code># dpkg -l | grep mysql-common
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Check-Installed-Package.png" alt="Check Installed Packages in Linux"></p><p><em>檢查安裝的軟件包</em></p><p>另外一種方式來判斷一個軟件包是否已安裝。</p><pre><code># dpkg --status package_name 		[Debian版和衍生版]
# rpm -q package_name 			[CentOS版 / openSUSE版]
</code></pre><p>例如，讓我們找出sysdig軟件包是否安裝在我們的系統。</p><pre><code># rpm -qa | grep sysdig
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Check-sysdig-Package.png" alt="Check sysdig Package"></p><p><em>檢查sysdig軟件包</em></p><p>####4. 查詢一個文件是由哪個軟件包安裝的####</p><pre><code># dpkg --search file_name
# rpm -qf file_name
</code></pre><p>例如，pw_dict.hwm文件是由那個軟件包安裝的？</p><pre><code># rpm -qf /usr/share/cracklib/pw_dict.hwm
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Query-File-in-Linux.png" alt="Query File in Linux"></p><p><em>Linux中查詢文件</em></p><h3 id="高級工具的常見用法" tabindex="-1">高級工具的常見用法 <a class="header-anchor" href="#高級工具的常見用法" aria-label="Permalink to “高級工具的常見用法”">​</a></h3><p>使用高級工具處理最常見的任務如下。</p><p>####1. 搜索軟件包####</p><p>aptitude的更新操作將會更新可用的軟件包列表，而aptitude的搜索操作會根據軟件包名進行實際搜索。</p><pre><code># aptitude update &amp;&amp; aptitude search package_name
</code></pre><p>在search all選項中，yum不僅可以通過軟件包名還可以通過軟件包的描述搜索。</p><pre><code># yum search package_name
# yum search all package_name
# yum whatprovides “*/package_name”
</code></pre><p>假定我們需要一個名為sysdig文件，想知道我們需要安裝哪個軟件包才行，那麼運行。</p><pre><code># yum whatprovides “*/sysdig”
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Check-Package-Description.png" alt="Check Package Description in Linux"></p><p><em>檢查軟件包描述</em></p><p>whatprovides告訴yum搜索一個含有能夠匹配上述正則表達式的文件的軟件包。</p><pre><code># zypper refresh &amp;&amp; zypper search package_name		[在openSUSE上]
</code></pre><p>####2. 從倉庫安裝一個軟件包####</p><p>當安裝一個軟件包時，在軟件包管理器解決了所有依賴性問題後，可能會提醒你確認安裝。需要注意的是運行更新（ update）或刷新（refresh）（根據所使用的軟件包管理器）不是絕對必要，但是考慮到安全性和依賴性的原因，保持安裝的軟件包是最新的是系統管理員的一個好經驗。</p><pre><code># aptitude update &amp;&amp; aptitude install package_name 		[Debian版和衍生版]
# yum update &amp;&amp; yum install package_name 			[CentOS版]
# zypper refresh &amp;&amp; zypper install package_name 		[openSUSE版]
</code></pre><p>####3. 卸載軟件包####</p><p>remove選項將會卸載軟件包，但把配置文件保留完好，然而purge選項將從系統中完全刪去該程序以及相關內容。</p><pre><code># aptitude remove / purge package_name
# yum erase package_name

---注意要卸載的openSUSE包前面的減號 ---

# zypper remove -package_name
</code></pre><p>在默認情況下，大部分（如果不是全部的話）的軟件包管理器會提示你，在你實際卸載之前你是否確定要繼續卸載。所以，請仔細閲讀屏幕上的信息，以避免陷入不必要的麻煩！</p><p>####4. 顯示軟件包的信息####</p><p>下面的命令將會顯示birthday這個軟件包的信息。</p><pre><code># aptitude show birthday
# yum info birthday
# zypper info birthday
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Check-Package-Information.png" alt="Check Package Information in Linux"></p><p><em>檢查包信息</em></p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>作為一個系統管理員，軟件包管理器是你不能迴避的東西。你應該立即去使用本文中介紹的這些工具。希望你在準備LFCS考試和日常工作中會覺得這些工具好用。歡迎在下面留下您的意見或問題，我們將盡可能快的回覆你。</p><hr>`,43)),p("p",null,[t[12]||(t[12]=e("via： ",-1)),a(n,{href:"http://www.tecmint.com/linux-package-management/"},{default:i(()=>[...t[11]||(t[11]=[e("http://www.tecmint.com/linux-package-management/",-1)])]),_:1})]),p("p",null,[t[16]||(t[16]=e("作者：",-1)),a(n,{href:"http://www.tecmint.com/author/gacanepa/"},{default:i(()=>[...t[13]||(t[13]=[e("Gabriel Cánepa",-1)])]),_:1}),t[17]||(t[17]=e(" 譯者：",-1)),a(n,{href:"https://github.com/Flowsnow"},{default:i(()=>[...t[14]||(t[14]=[e("Flowsnow",-1)])]),_:1}),t[18]||(t[18]=e(" 校對：",-1)),a(n,{href:"https://github.com/wxy"},{default:i(()=>[...t[15]||(t[15]=[e("wxy",-1)])]),_:1})]),p("p",null,[t[21]||(t[21]=e("本文由 ",-1)),a(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[19]||(t[19]=[e("LCTT",-1)])]),_:1}),t[22]||(t[22]=e(" 原創翻譯，",-1)),a(n,{href:"https://linux.cn/"},{default:i(()=>[...t[20]||(t[20]=[e("Linux中國",-1)])]),_:1}),t[23]||(t[23]=e(" 榮譽推出",-1))])])}const y=d(o,[["render",s]]);export{x as __pageData,y as default};
